        *instruct = stack_instruct(i->b, file, i->a);
        for (i->ln = 0; (i->b = my_str_to_selec_array(file[++i->a], ' ')) &&
            i->b[0][my_strlen(i->b[0]) - 1] != LABEL_CHAR; i->ln++);
