int find_posi_new_pc_instruction(char *map, int pc, int *new_posi)
{
    int instruct = 0;

    *new_posi = pc;
    if (*new_posi < 0)
        *new_posi *= -1;
    while (*new_posi >= MEM_SIZE)
        *new_posi -= MEM_SIZE;
    if (*new_posi < 0)
        *new_posi *= -1;
    for (int cicle = 0; map && cicle < 5;) {
        instruct = map[*new_posi];
        if (instruct >= 1 && instruct <= 16)
            return (instruct);
        *new_posi += 1;
        if (*new_posi >= MEM_SIZE) {
            *new_posi = 0;
            cicle += 1;
        }
    }
    return (84);
}

