int *i, unsigned short *player_count)
{
    for (; av[*i] && (!my_strcmp(av[*i], "-n") || !my_strcmp(av[*i], "-a"));
        *i += 2) {
        if (!(av[*i + 1] && my_str_isnum(av[*i + 1])))
            return (true);
    }
