    for (int i = f(str, e); str[i] != '\0'; a++, length = 0, start = i) {
        for (; str[i] != ' ' && str[i] && str[i] != e && str[i] != '\t'; i++)
            length++;
        if ((array[a] = my_malloc(sizeof(char) * (length + 2), 0)) == NULL)
